/// System tray icons derived from the Hive hexagon mark (`HiveHexMark`).
///
/// Each value is the full Flutter asset key (`packages/design_system/...`),
/// which is what tray plugins expect when they load an icon from the app's
/// asset bundle. The files live in `design_system/assets/tray/` and are
/// generated by `design_system/tool/generate_tray_icons.py`.
///
/// Pick one per OS behind the platform tray abstraction; never branch on the
/// platform inline.
abstract final class HiveTrayAssets {
  static const String _root = 'packages/design_system/assets/tray';

  /// Windows tray icon: a multi-size `.ico` (16, 20, 24, 32, 40, 48 and 64)
  /// in the `accent` and `onAccent` colors.
  static const String windows = '$_root/hive_tray_windows.ico';

  /// Linux tray icon: a 32x32 `.png` in the `accent` and `onAccent` colors.
  static const String linux = '$_root/hive_tray_linux.png';

  /// Linux tray icon for high-density panels: a 64x64 `.png`.
  static const String linux2x = '$_root/hive_tray_linux@2x.png';

  /// macOS menu bar template icon: a 22x22 `.png`, black with alpha only.
  ///
  /// Mark it as a template image so macOS tints it for the menu bar
  /// appearance.
  static const String macosTemplate = '$_root/hive_tray_macos_template.png';

  /// macOS menu bar template icon for Retina displays: a 44x44 `.png`.
  static const String macosTemplate2x =
      '$_root/hive_tray_macos_template@2x.png';

  /// Every tray icon asset key.
  static const List<String> all = <String>[
    windows,
    linux,
    linux2x,
    macosTemplate,
    macosTemplate2x,
  ];
}
